main(){
    char s[100],r[100];
    int i,j=0,len;
    char t;
    scanf("%s", s);
    for(i=0;s[i]!='\0';i++)
        if(s[i]%3!=0) r[j++]=s[i];
    r[j]='\0';
    len=j;
    for(i=0;i<len-1;i++)
        for(j=0;j<len-1-i;j++)
            if(r[j]>r[j+1]){t=r[j];r[j]=r[j+1];r[j+1]=t;}
    printf("%s",r);
}

#include<stdio.h>
main(){
    char s[200],r[200];
    int i=0,j=0,k,start,end,len;
    scanf("%s", s);
    while(s[i]=='*'){r[j++]=s[i];i++;}
    start=j;
    for(;s[i]!='\0';i++)
        if(s[i]!='*') r[j++]=s[i];
    end=j-1;
    i=0;
    while(s[i]!='\0') i++;
    len=i;
    for(k=len-1;k>=0&&s[k]=='*';k--)
        r[j++]=s[k];
    r[j]='\0';
    printf("%s",r);
}

