#include<stdio.h>
main()
{
    int speed[5]={8,10,13,16,18};
    int n[5],i,t,best,bestid;
    for(i=0;i<5;i++)
        scanf("%d",&n[i]);
    best=n[0]*speed[0];
    bestid=1;
    for(i=1;i<5;i++)
    {
        t=n[i]*speed[i];
        if(t<best)
        {
            best=t;
            bestid=i+1;
        }
    }
    printf("最短排队用时%d秒，建议去%d号窗口",best,bestid);
}

