#include<stdio.h>
main()
{
    int a[100],n=0,x,i,j,t,count,found=0;
    while(1){scanf("%d",&x);if(x==0)break;a[n++]=x;}
    for(i=0;i<n-1;i++)for(j=0;j<n-1-i;j++)if(a[j]>a[j+1]){t=a[j];a[j]=a[j+1];a[j+1]=t;}
    for(i=0;i<n;i++)
    {
        if(i>0&&a[i]==a[i-1])continue;
        count=0;
        for(j=0;j<n;j++)if(a[j]==a[i])count++;
        if(count==3){printf("%d\n",a[i]);found=1;}
    }
    if(found==0)printf("没有幸运数字");
}

