#include<stdio.h>
#include<string.h>
main()
{
    char s[100];
    int i,len,d=0,a=0,o=0;
    scanf("%s",s);
    len=strlen(s);
    for(i=0;i<len;i++)
    {
        if(s[i]>='0'&&s[i]<='9')d=1;
        else if((s[i]>='a'&&s[i]<='z')||(s[i]>='A'&&s[i]<='Z'))a=1;
        else o=1;
    }
    if(len<6)printf("弱");
    else if(d&&a&&o)printf("强");
    else if(d&&a)printf("中");
    else printf("弱");
}

