#include<stdio.h>
#include<string.h>
main()
{
    char name[20][20],s[20],tmp[20];
    int score[20]={0},first[20],n=0,i,j,k,add[3]={3,2,1},ts,tf,idx;
    for(i=0;i<20;i++)first[i]=i;
    for(i=0;i<3;i++)
        for(j=0;j<3;j++)
        {
            scanf("%s",s);
            idx=-1;
            for(k=0;k<n;k++)if(strcmp(name[k],s)==0)idx=k;
            if(idx==-1){idx=n;strcpy(name[n],s);first[n]=n;n++;}
            score[idx]+=add[j];
        }
    for(i=0;i<n-1;i++)for(j=0;j<n-1-i;j++)
        if(score[j]<score[j+1]||(score[j]==score[j+1]&&first[j]>first[j+1]))
        {
            ts=score[j];score[j]=score[j+1];score[j+1]=ts;
            tf=first[j];first[j]=first[j+1];first[j+1]=tf;
            strcpy(tmp,name[j]);strcpy(name[j],name[j+1]);strcpy(name[j+1],tmp);
        }
    for(i=0;i<3;i++)printf("第%d名：%s %d分\n",i+1,name[i],score[i]);
}

