#include<stdio.h>
main()
{
    int s[7],d[7],i,normal=0,maxs,maxd;
    for(i=0;i<7;i++)scanf("%d%d",&s[i],&d[i]);
    maxs=s[0];maxd=d[0];
    for(i=0;i<7;i++)
    {
        if(s[i]>=90&&s[i]<=140&&d[i]>=60&&d[i]<=90)normal++;
        if(s[i]>maxs)maxs=s[i];
        if(d[i]>maxd)maxd=d[i];
    }
    printf("血压正常天数：%d天\n",normal);
    printf("最高收缩压：%d\n",maxs);
    printf("最高舒张压：%d",maxd);
}
